add_filter( 'woocommerce_shop_order_search_results', 'perfectpixel_search_orders_by_sku', 10, 2 );
add_filter( 'woocommerce_cot_shop_order_search_results', 'perfectpixel_search_orders_by_sku', 10, 2 );

function perfectpixel_search_orders_by_sku( $order_ids, $term ) {
	global $wpdb;
	$term = trim( wc_clean( (string) $term ) );
	if ( mb_strlen( $term ) < 2 ) {
		return $order_ids;
	}
	$product_ids = $wpdb->get_col(
		$wpdb->prepare( "SELECT product_id FROM {$wpdb->prefix}wc_product_meta_lookup WHERE sku LIKE %s LIMIT 200", '%' . $wpdb->esc_like( $term ) . '%' )
	);
	if ( ! $product_ids ) {
		return $order_ids;
	}
	$in    = implode( ',', array_map( 'intval', $product_ids ) );
	$found = $wpdb->get_col(
		"SELECT DISTINCT i.order_id FROM {$wpdb->prefix}woocommerce_order_items i
		INNER JOIN {$wpdb->prefix}woocommerce_order_itemmeta m ON m.order_item_id = i.order_item_id
		WHERE i.order_item_type = 'line_item' AND m.meta_key IN ('_product_id','_variation_id') AND m.meta_value IN ({$in})"
	);
	return array_values( array_unique( array_merge( array_map( 'intval', (array) $order_ids ), array_map( 'intval', $found ) ) ) );
}
